import{_ as a,o,c as t,a3 as r}from"./chunks/framework.DACwFHq9.js";const h=JSON.parse(`{"title":"AI Overview","description":"Learn about Notely's 13-domain modular, local-first AI platform, AIFlow master orchestrator, and Context Compaction engine.","frontmatter":{"title":"AI Overview","description":"Learn about Notely's 13-domain modular, local-first AI platform, AIFlow master orchestrator, and Context Compaction engine.","keywords":"ai, local llm, openai, huggingface, vector database, knowledge graph, AIFlow, compaction","category":"AI"},"headers":[],"relativePath":"ai/index.md","filePath":"ai/index.md","lastUpdated":1787158574000}`),i={name:"ai/index.md"};function n(s,e,l,c,d,m){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="ai-subsystem-overview" tabindex="-1">AI Subsystem Overview <a class="header-anchor" href="#ai-subsystem-overview" aria-label="Permalink to &quot;AI Subsystem Overview&quot;">​</a></h1><p>Notely features a 13-domain modular, local-first AI platform designed around private data control. Markdown files remain the absolute source of truth, parsed and indexed into offline-first databases to fuel assistant reasoning.</p><hr><h2 id="capabilities-at-a-glance" tabindex="-1">Capabilities at a Glance <a class="header-anchor" href="#capabilities-at-a-glance" aria-label="Permalink to &quot;Capabilities at a Glance&quot;">​</a></h2><h3 id="_1-master-flow-orchestrator-aiflow-js-13-domain-architecture" tabindex="-1">1. Master Flow Orchestrator (<code>AIFlow.js</code>) &amp; 13-Domain Architecture <a class="header-anchor" href="#_1-master-flow-orchestrator-aiflow-js-13-domain-architecture" aria-label="Permalink to &quot;1. Master Flow Orchestrator (`AIFlow.js`) &amp; 13-Domain Architecture&quot;">​</a></h3><ul><li>All LLM queries flow through <strong><code>AIFlow.js</code></strong>, executing a 5-stage pipeline across 13 decoupled domain module facades (<code>compaction</code>, <code>planner</code>, <code>personas</code>, <code>prompts</code>, <code>context</code>, <code>graph</code>, <code>embeddings</code>, <code>memory</code>, <code>executor</code>, <code>tools</code>, <code>grounding</code>, <code>formatter</code>, <code>testing</code>).</li></ul><h3 id="_2-zero-latency-context-compaction-ai-compaction" tabindex="-1">2. Zero-Latency Context Compaction (<code>ai/compaction/</code>) <a class="header-anchor" href="#_2-zero-latency-context-compaction-ai-compaction" aria-label="Permalink to &quot;2. Zero-Latency Context Compaction (`ai/compaction/`)&quot;">​</a></h3><ul><li>Automatically compacts long chat sessions (&gt;4 messages) into an Executive Memory Summary + recent 4 turns verbatim, slashing LLM input tokens by <strong>~75-80%</strong> with 0ms overhead.</li></ul><h3 id="_3-sqlite-knowledge-graph" tabindex="-1">3. SQLite Knowledge Graph <a class="header-anchor" href="#_3-sqlite-knowledge-graph" aria-label="Permalink to &quot;3. SQLite Knowledge Graph&quot;">​</a></h3><ul><li>Outbound relations, tags, and CTE traversals mapped into <code>ai-graph.db</code>.</li><li>Visualized interactively in the sidebar.</li></ul><h3 id="_4-local-embedding-indexer" tabindex="-1">4. Local Embedding Indexer <a class="header-anchor" href="#_4-local-embedding-indexer" aria-label="Permalink to &quot;4. Local Embedding Indexer&quot;">​</a></h3><ul><li>High-performance <code>ai-embeddings.db</code> storing note chunk vectors.</li><li>Runs entirely offline using a local ONNX runtime for <code>BGE-small-en-v1.5</code> embeddings, or falls back to HuggingFace APIs.</li><li>Background Index Worker priority queues processing note changes debounced.</li></ul><h3 id="_5-persona-registry-markdown-source-of-truth" tabindex="-1">5. Persona Registry (Markdown Source of Truth) <a class="header-anchor" href="#_5-persona-registry-markdown-source-of-truth" aria-label="Permalink to &quot;5. Persona Registry (Markdown Source of Truth)&quot;">​</a></h3><ul><li>All personas (builtin and custom) use <code>.md</code> files with YAML frontmatter as their authoritative Source of Truth.</li><li>SQLite (<code>personas.db</code>) acts strictly as an index registry. Custom personas persist as formatted <code>.md</code> files to disk (<code>appData/personas/*.md</code>).</li><li>Customize instructions, descriptions, metadata, and preset avatar icons (🤖, 💻, 🧠, etc.).</li></ul><h3 id="_6-diagnostics-flow-telemetry-trace-logs" tabindex="-1">6. Diagnostics, Flow Telemetry &amp; Trace Logs <a class="header-anchor" href="#_6-diagnostics-flow-telemetry-trace-logs" aria-label="Permalink to &quot;6. Diagnostics, Flow Telemetry &amp; Trace Logs&quot;">​</a></h3><ul><li>Professional <strong>AI Health</strong> panel to verify subsystem initialization.</li><li><strong>Flow Telemetry</strong> tab displaying 5-stage timeline cards, system prompt viewer (Copy/Expand), tool calls, compaction stats, and latency breakdown.</li></ul>',16)])])}const p=a(i,[["render",n]]);export{h as __pageData,p as default};
